--   ```
--
-- * Dropping a UDT column from a table is supported.
--
--   ```sql
--   ALTER TABLE t_udt DROP c2;
--   ```
--
-- * Renaming a UDT column in a table is supported.
--
--   ```sql
--   ALTER TABLE t_udt RENAME COLUMN c2 TO b2;
--   ```
