-- # ALTER ROLE
--
-- ## Purpose
--
-- This statement is used to modify the authentication method of a role.
--
--   <main id="notice" type='explain'>
--     <h4>Note</h4>
--     <p> User sessions of the modified role are not affected. </p>
--   </main>
--
-- ## Syntax
--
-- ```sql
-- ALTER ROLE role_name
-- { NOT IDENTIFIED
-- | IDENTIFIED BY password
-- } ;
-- ```
